-- Terviq AI administrator database extension.
-- Core member tables are created by app/dashboard/database/schema.sql.
alter table public.profiles add column if not exists account_status text not null default 'active' check(account_status in ('active','suspended'));
create table if not exists public.app_settings(key text primary key,value jsonb not null default '{}'::jsonb,updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now());
create table if not exists public.admin_audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id) on delete set null,action text not null,target text not null,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.deposit_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,amount numeric(18,2) not null check(amount>0),currency text not null default 'NGN',method text not null,proof_url text,reference text unique,status text not null default 'pending' check(status in ('pending','approved','rejected')),reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.withdrawal_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,amount numeric(18,2) not null check(amount>0),fee numeric(18,2) not null default 0 check(fee>=0),net_amount numeric(18,2) not null check(net_amount>=0),destination jsonb not null default '{}'::jsonb,source text not null default 'earnings' check(source in ('earnings','referrals')),status text not null default 'pending' check(status in ('pending','approved','rejected','paid')),reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now());
alter table public.app_settings enable row level security;alter table public.admin_audit_logs enable row level security;alter table public.deposit_requests enable row level security;alter table public.withdrawal_requests enable row level security;
insert into public.app_settings(key,value) values('referral_rate_percent','{"percent":10}'::jsonb),('withdrawal_rules','{"minimum":5000,"daily_maximum":2500000,"weekday_fee_percent":15,"free_day_of_month":30}'::jsonb),('deposit_methods','{"currency":"NGN","crypto_discount_percent":9,"methods":["BTC","LTC","USDT_TRC20","USDT_BEP20","BNB","TRX"]}'::jsonb),('admin_emails','{"emails":[]}'::jsonb) on conflict(key) do nothing;
drop policy if exists "Members read own app settings" on public.app_settings;
create policy "Members read own app settings" on public.app_settings for select to authenticated using(key in ('referral_rate_percent','withdrawal_rules','deposit_methods'));
drop policy if exists "Members read own deposit requests" on public.deposit_requests;
create policy "Members read own deposit requests" on public.deposit_requests for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "Members create own deposit requests" on public.deposit_requests;
create policy "Members create own deposit requests" on public.deposit_requests for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists "Members read own withdrawal requests" on public.withdrawal_requests;
create policy "Members read own withdrawal requests" on public.withdrawal_requests for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "Members create own withdrawal requests" on public.withdrawal_requests;
create policy "Members create own withdrawal requests" on public.withdrawal_requests for insert to authenticated with check((select auth.uid())=user_id);
revoke all on public.admin_audit_logs,public.app_settings from anon,authenticated;
grant select on public.app_settings to authenticated;
grant select,insert on public.deposit_requests,public.withdrawal_requests to authenticated;
create schema if not exists private;
revoke all on schema private from public,anon,authenticated;
grant usage on schema private to authenticated;
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path='' as $$
 select coalesce((auth.jwt()->'app_metadata'->>'role')='admin',false) or exists(select 1 from public.app_settings s where s.key='admin_emails' and lower(coalesce(auth.jwt()->>'email',''))=any(array(select lower(jsonb_array_elements_text(s.value->'emails')))))
$$;
create or replace function private.list_users() returns table(id uuid,email text,full_name text,created_at timestamptz,account_status text) language plpgsql security definer set search_path='' as $$
begin if not private.is_admin() then raise exception 'Administrator access only'; end if; return query select u.id,u.email,coalesce(p.full_name,u.raw_user_meta_data->>'full_name',''),u.created_at,coalesce(p.account_status,'active') from auth.users u left join public.profiles p on p.id=u.id order by u.created_at desc limit 1000; end; $$;
create or replace function private.set_user_status(p_user_id uuid,p_status text) returns void language plpgsql security definer set search_path='' as $$
begin if not private.is_admin() then raise exception 'Administrator access only'; end if; if p_status not in ('active','suspended') then raise exception 'Invalid status'; end if; update public.profiles set account_status=p_status,updated_at=now() where id=p_user_id; if not found then raise exception 'User not found'; end if; insert into public.admin_audit_logs(actor_id,action,target,details) values(auth.uid(),'user.status_changed',p_user_id::text,jsonb_build_object('status',p_status)); end; $$;
create or replace function private.delete_user(p_user_id uuid) returns void language plpgsql security definer set search_path='' as $$
begin if not private.is_admin() then raise exception 'Administrator access only'; end if; if p_user_id=auth.uid() then raise exception 'Cannot delete your own admin account'; end if; delete from auth.users where id=p_user_id; if not found then raise exception 'User not found'; end if; insert into public.admin_audit_logs(actor_id,action,target) values(auth.uid(),'user.deleted',p_user_id::text); end; $$;
create or replace function private.set_referral_rate(p_rate numeric) returns void language plpgsql security definer set search_path='' as $$
begin if not private.is_admin() then raise exception 'Administrator access only'; end if; if p_rate<0 or p_rate>100 then raise exception 'Invalid rate'; end if; insert into public.app_settings(key,value,updated_by,updated_at) values('referral_rate_percent',jsonb_build_object('percent',p_rate),auth.uid(),now()) on conflict(key) do update set value=excluded.value,updated_by=excluded.updated_by,updated_at=now(); insert into public.admin_audit_logs(actor_id,action,target,details) values(auth.uid(),'settings.referral_rate_updated','referral_rate_percent',jsonb_build_object('rate',p_rate)); end; $$;
create or replace function private.overview() returns jsonb language plpgsql security definer set search_path='' as $$
begin if not private.is_admin() then raise exception 'Administrator access only'; end if; return jsonb_build_object('users',(select count(*) from auth.users),'investors',(select count(distinct user_id) from public.investments where status in ('active','matured')),'referrals',(select count(*) from public.referrals),'referralPaid',(select coalesce(sum(commission_amount),0) from public.referrals where status='credited'),'earnings',(select coalesce(sum(amount),0) from public.transactions where type in ('profit_withdrawal','referral_withdrawal') and status='completed'),'deposits',jsonb_build_object('daily',(select coalesce(sum(amount),0) from public.transactions where type='deposit' and status='completed' and created_at>=date_trunc('day',now())),'weekly',(select coalesce(sum(amount),0) from public.transactions where type='deposit' and status='completed' and created_at>=now()-interval '7 days'),'monthly',(select coalesce(sum(amount),0) from public.transactions where type='deposit' and status='completed' and created_at>=date_trunc('month',now())),'all',(select coalesce(sum(amount),0) from public.transactions where type='deposit' and status='completed')),'investments',jsonb_build_object('daily',(select coalesce(sum(principal_amount),0) from public.investments where status<>'cancelled' and created_at>=date_trunc('day',now())),'weekly',(select coalesce(sum(principal_amount),0) from public.investments where status<>'cancelled' and created_at>=now()-interval '7 days'),'monthly',(select coalesce(sum(principal_amount),0) from public.investments where status<>'cancelled' and created_at>=date_trunc('month',now())),'all',(select coalesce(sum(principal_amount),0) from public.investments where status<>'cancelled'))); end; $$;
revoke all on function private.is_admin(),private.list_users(),private.set_user_status(uuid,text),private.delete_user(uuid),private.set_referral_rate(numeric),private.overview() from public,anon,authenticated;
grant execute on function private.is_admin(),private.list_users(),private.set_user_status(uuid,text),private.delete_user(uuid),private.set_referral_rate(numeric),private.overview() to authenticated;
create or replace function public.is_terviq_admin() returns boolean language sql stable security invoker set search_path='' as $$ select private.is_admin() $$;
create or replace function public.admin_list_users() returns table(id uuid,email text,full_name text,created_at timestamptz,account_status text) language sql security invoker set search_path='' as $$ select * from private.list_users() $$;
create or replace function public.admin_set_user_status(p_user_id uuid,p_status text) returns void language sql security invoker set search_path='' as $$ select private.set_user_status(p_user_id,p_status) $$;
create or replace function public.admin_delete_user(p_user_id uuid) returns void language sql security invoker set search_path='' as $$ select private.delete_user(p_user_id) $$;
create or replace function public.admin_set_referral_rate(p_rate numeric) returns void language sql security invoker set search_path='' as $$ select private.set_referral_rate(p_rate) $$;
create or replace function public.admin_overview() returns jsonb language sql security invoker set search_path='' as $$ select private.overview() $$;
revoke all on function public.is_terviq_admin(),public.admin_list_users(),public.admin_set_user_status(uuid,text),public.admin_delete_user(uuid),public.admin_set_referral_rate(numeric),public.admin_overview() from public,anon;
grant execute on function public.is_terviq_admin(),public.admin_list_users(),public.admin_set_user_status(uuid,text),public.admin_delete_user(uuid),public.admin_set_referral_rate(numeric),public.admin_overview() to authenticated;
